3	const readStdin = async (): Promise<string> => {
4	  const chunks: Buffer[] = [];
5	  for await (const chunk of process.stdin) chunks.push(chunk as Buffer);
6	  return Buffer.concat(chunks).toString("utf8");
7	};
8	
9	const main = async (): Promise<void> => {
10	  try {
11	    const scenario = JSON.parse(await readStdin());
12	    process.stdout.write(JSON.stringify(runScenario(scenario)));
13	  } catch (err) {
14	    process.stderr.write(`${(err as Error).message}\n`);
15	    process.exit(1);
16	  }
17	};
18	
19	void main();
