43	// === Generic helpers ===
44	const sumBy = <T>(items: T[], selector: (item: T) => number): number =>
45	  items.reduce((sum, item) => sum + selector(item), 0);
46	
47	const rateIfApplies = (applies: boolean, base: number, rate: number): number =>
